CREATE OR REPLACE FORCE EDITIONABLE VIEW "PPPT"."PERSONALPUESTO" ("IDPERSONAL", "IDPUESTO", "NOMBRE", "WAIS", "THERMAN", "SPRANGER", "HERMAN", "CLEAVER", "EXPERIENCIA", "ESCOLARIDAD", "TOTAL", "PUESTO") AS 
  SELECT Personal.IdPersonal, Puestos.IdPuesto, Personal.Nombre, Compatibilidad.Wais, Compatibilidad.Therman, Compatibilidad.Spranger, Compatibilidad.Herman, Compatibilidad.Cleaver, Compatibilidad.Experiencia, Compatibilidad.Escolaridad, Compatibilidad.Total, Puestos.Puesto FROM (Compatibilidad INNER JOIN Personal ON Compatibilidad.IdPersonal = Personal.IdPersonal) INNER JOIN Puestos ON Compatibilidad.IdPuesto = Puestos.IdPuesto;
